# 4.8 — Defender và Windows Update: 1116/1117 (phát hiện/xử lý), 5007 (đổi cấu hình — thêm loại trừ), 5001 (tắt bảo vệ thời gian thực), WindowsUpdateClient 19/20.
# Mẫu: tc/defender-5007.evtx (EVTX-to-MITRE-Attack), tc/defender-atomic-1116-1117.evtx (EVTX-ATTACK-SAMPLES, chạy Atomic Red Team 2019), system.evtx + 2-vss_7-System.evtx.
@ps evtx-rec tc/defender-5007.evtx | ConvertFrom-Json | ForEach-Object { $c = $(if ($_.data.'New Value') { 'THÊM ' + $_.data.'New Value' } else { 'BỎ   ' + $_.data.'Old Value' }); '{0}  {1}' -f $_.t.ToString('HH:mm:ss'), ($c -replace 'HKLM\\SOFTWARE\\Microsoft\\Windows Defender\\','') }
@ps evtx-rec tc/defender-atomic-1116-1117.evtx | ConvertFrom-Json | Sort-Object t | ForEach-Object { '{0}  {1}  {2,-32} {3}' -f $_.t.ToString('HH:mm:ss'), $_.id, $_.data.'Threat Name', (($_.data.Path -replace '^.*atomics\\','') -replace '->.*','') }
@ps evtx-rec tc/defender-atomic-1116-1117.evtx | ConvertFrom-Json | Where-Object id -eq 1117 | Select-Object -First 1 | ForEach-Object { $_.data | Format-List 'Threat Name','Severity Name','Category Name','Process Name','Detection User','Action ID','Error Code','Error Description','Remediation User','Signature Version' }
@ps $e = evtx-rec tc/defender-atomic-1116-1117.evtx | ConvertFrom-Json; $xl = $e | Where-Object id -eq 1117 | ForEach-Object { $_.data.'Threat Name' }; $e | Where-Object id -eq 1116 | Group-Object { $_.data.'Threat Name' } | ForEach-Object { '{0,-32} phát hiện {1} lần · có 1117: {2}' -f $_.Name, $_.Count, ($xl -contains $_.Name) }
# 5001 (tắt Real-time protection) không có trong bộ mẫu công khai — đếm thật:
evtx-rec mau/*.evtx tc/*.evtx 2>/dev/null | jq -r 'select(.id==5001 and (.nguon|test("Defender"))) | .id' | wc -l
@ps evtx-rec mau/system.evtx mau/2-vss_7-System.evtx 2>$null | ConvertFrom-Json | Where-Object { $_.nguon -match 'WindowsUpdateClient' -and $_.id -in 19,20 } | Group-Object id | Select-Object Count,@{n='Id';e={$_.Name}} | Format-Table -AutoSize
@ps evtx-rec mau/system.evtx mau/2-vss_7-System.evtx 2>$null | ConvertFrom-Json | Where-Object { $_.nguon -match 'WindowsUpdateClient' -and $_.id -eq 20 } | ForEach-Object { '{0}  {1}  {2}' -f $_.t.ToString('yyyy-MM-dd'), $_.data.errorCode, ($_.data.updateTitle -replace ' for x64-based Systems','') }
@ps $ok = @(evtx-rec mau/system.evtx 2>$null | ConvertFrom-Json | Where-Object { $_.nguon -match 'WindowsUpdateClient' -and $_.id -eq 19 -and $_.data.updateTitle -match 'KB4025342' }); 'KB4025342 cài thành công (19): {0} lần; sự kiện cuối của log: {1}' -f $ok.Count, (evtx-rec mau/system.evtx 2>$null | ConvertFrom-Json | Select-Object -Last 1).t.ToString('yyyy-MM-dd')
